package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	parts := strings.Fields(line)
	n := parseInt(parts[0])
	m := parseInt(parts[1])
	k := parseInt(parts[2])

	// a[i][j] = buy price on planet i for item j
	// b[i][j] = sell price on planet i for item j
	// c[i][j] = count of item j on planet i
	a := make([][]int, n)
	b := make([][]int, n)
	c := make([][]int, n)

	for i := 0; i < n; i++ {
		// read planet name
		nameLine, _ := reader.ReadString('\n')
		_ = nameLine
		a[i] = make([]int, m)
		b[i] = make([]int, m)
		c[i] = make([]int, m)
		for j := 0; j < m; j++ {
			line, _ := reader.ReadString('\n')
			fields := strings.Fields(line)
			a[i][j] = parseInt(fields[0])
			b[i][j] = parseInt(fields[1])
			c[i][j] = parseInt(fields[2])
		}
	}

	// For each pair of planets (buy planet i, sell planet j), i != j
	// We want to maximize profit = sum over items of (sell_price - buy_price) * quantity
	// subject to:
	//   quantity <= c[i][j] (buy limit on planet i)
	//   total quantity <= k
	//   quantity >= 0
	//   sell_price - buy_price can be negative, so we only take items with positive profit

	maxProfit := 0

	for buyPlanet := 0; buyPlanet < n; buyPlanet++ {
		for sellPlanet := 0; sellPlanet < n; sellPlanet++ {
			if buyPlanet == sellPlanet {
				continue
			}
			// For each item type, compute the profit per unit
			// We can buy up to c[buyPlanet][j] items of type j
			// Profit per unit = b[sellPlanet][j] - a[buyPlanet][j]
			// We want to pick quantities x_j such that sum x_j <= k, 0 <= x_j <= c[buyPlanet][j]
			// maximizing sum (b[sellPlanet][j] - a[buyPlanet][j]) * x_j

			// This is a bounded knapsack problem where each item type j has:
			//   weight = 1 (per unit)
			//   value = b[sellPlanet][j] - a[buyPlanet][j]
			//   count = c[buyPlanet][j]
			// capacity = k

			// Since each unit has weight 1, we can think of it as:
			// We have multiple copies of each item type. We want to pick up to k units total.
			// The optimal strategy is to pick the units with the highest profit per unit first.

			// So we can create a list of all available units with their profits, sort in descending order,
			// and take the top k (or fewer if not enough units).

			type unit struct {
				profit int
			}

			units := make([]unit, 0)
			for j := 0; j < m; j++ {
				profit := b[sellPlanet][j] - a[buyPlanet][j]
				if profit <= 0 {
					continue
				}
				count := c[buyPlanet][j]
				for x := 0; x < count; x++ {
					units = append(units, unit{profit: profit})
				}
			}

			// Sort units by profit descending
			sortUnits(units)

			// Take up to k units with highest profit
			profit := 0
			for idx := 0; idx < len(units) && idx < k; idx++ {
				profit += units[idx].profit
			}

			if profit > maxProfit {
				maxProfit = profit
			}
		}
	}

	fmt.Println(maxProfit)
}

func parseInt(s string) int {
	var result int
	for _, ch := range s {
		result = result*10 + int(ch-'0')
	}
	return result
}

// Simple insertion sort for units by profit descending
func sortUnits(units []struct {
	profit int
}) {
	for i := 1; i < len(units); i++ {
		key := units[i]
		j := i - 1
		for j >= 0 && units[j].profit < key.profit {
			units[j+1] = units[j]
			j--
		}
		units[j+1] = key
	}
}
