			parts := strings.Fields(line)
			a[i][j] = atoi(parts[0])
			b[i][j] = atoi(parts[1])
			c[i][j] = atoi(parts[2])
		}
	}

	// For each pair of planets (buy from i, sell to j), compute max profit
	maxProfit := 0

	for buyPlanet := 0; buyPlanet < n; buyPlanet++ {
		for sellPlanet := 0; sellPlanet < n; sellPlanet++ {
			if buyPlanet == sellPlanet {
				continue
			}
			// For each item type, compute the profit per item if we buy on buyPlanet and sell on sellPlanet
			// profit[j] = b[sellPlanet][j] - a[buyPlanet][j]
			// We can buy at most c[buyPlanet][j] items of type j
			// We want to select items (up to k total) to maximize total profit
			// This is a bounded knapsack problem where each item type j has:
			//   value = profit[j] per unit
			//   weight = 1 per unit
			//   count = c[buyPlanet][j]
			//   capacity = k

			// If profit[j] <= 0, we don't want to buy that item
			// We can use a greedy approach: sort items by profit per unit (which is just profit[j] since weight is 1)
			// and take as many as possible of the highest profit items first

			// Create a list of (profit, count) for items with positive profit
			type item struct {
				profit int
				count  int
			}
			items := make([]item, 0, m)
			for j := 0; j < m; j++ {
				profit := b[sellPlanet][j] - a[buyPlanet][j]
				if profit > 0 {
					items = append(items, item{profit: profit, count: c[buyPlanet][j]})
				}
			}

			// Sort by profit descending
			sortItems(items)

			// Greedily take items
			remaining := k
			totalProfit := 0
			for _, it := range items {
				if remaining <= 0 {
					break
				}
				take := it.count
				if take > remaining {
					take = remaining
				}
				totalProfit += take * it.profit
				remaining -= take
			}

			if totalProfit > maxProfit {
				maxProfit = totalProfit
			}
		}
	}

	fmt.Println(maxProfit)
}

func atoi(s string) int {
	n := 0
	for _, ch := range s {
		n = n*10 + int(ch-'0')
	}
	return n
}

func sortItems(items []struct {
	profit int
	count  int
}) {
	// Simple bubble sort for small m (m <= 100)
	for i := 0; i < len(items); i++ {
		for j := 0; j < len(items)-1-i; j++ {
			if items[j].profit < items[j+1].profit {
				items[j], items[j+1] = items[j+1], items[j]
			}
		}
	}
}
