package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)

	// Read first line: n, m, k
	line, _ := reader.ReadString('\n')
	line = strings.TrimSpace(line)
	parts := strings.Fields(line)
	n := 0
	m := 0
	k := 0
	fmt.Sscanf(parts[0], "%d", &n)
	fmt.Sscanf(parts[1], "%d", &m)
	fmt.Sscanf(parts[2], "%d", &k)

	// Read n planets
	// For each planet, read name and then m lines of a, b, c
	type PlanetData struct {
		name string
		a    []int // buy cost
		b    []int // sell cost
		c    []int // count available
	}

	planets := make([]PlanetData, n)

	for i := 0; i < n; i++ {
		// Read planet name
		nameLine, _ := reader.ReadString('\n')
		nameLine = strings.TrimSpace(nameLine)
		planets[i].name = nameLine
		planets[i].a = make([]int, m)
		planets[i].b = make([]int, m)
		planets[i].c = make([]int, m)

		for j := 0; j < m; j++ {
			dataLine, _ := reader.ReadString('\n')
			dataLine = strings.TrimSpace(dataLine)
			dataParts := strings.Fields(dataLine)
			var a, b, c int
			fmt.Sscanf(dataParts[0], "%d", &a)
			fmt.Sscanf(dataParts[1], "%d", &b)
			fmt.Sscanf(dataParts[2], "%d", &c)
			planets[i].a[j] = a
			planets[i].b[j] = b
			planets[i].c[j] = c
		}
	}

	// For each pair of planets (buy from i, sell to j), i != j
	// We want to maximize profit = sum over items of (sell_price - buy_price) * quantity
	// Subject to:
	//   - quantity of item t on planet i <= c[i][t]
	//   - total quantity <= k
	//   - quantity >= 0
	//   - We only buy items where sell_price > buy_price (otherwise no profit)

	maxProfit := 0

	for buyPlanet := 0; buyPlanet < n; buyPlanet++ {
		for sellPlanet := 0; sellPlanet < n; sellPlanet++ {
			if buyPlanet == sellPlanet {
				continue
			}

			// For each item type, calculate the profit per unit if we buy on buyPlanet and sell on sellPlanet
			// profitPerUnit[j] = planets[sellPlanet].b[j] - planets[buyPlanet].a[j]
			// If profitPerUnit[j] <= 0, we don't want to trade this item
			// We have a bounded knapsack problem:
			//   items: m types
			//   weight of each item: 1
			//   value of each item: profitPerUnit[j]
			//   max count of item j: planets[buyPlanet].c[j]
			//   capacity: k
			//   maximize total value

			// DP: dp[w] = max profit using w items
			// dp[0] = 0
			// For each item type j:
			//   for w from k down to 0:
			//     for count from 1 to min(c[j], k-w):
			//       dp[w+count] = max(dp[w+count], dp[w] + count * profitPerUnit[j])

			// Actually, since each item has weight 1, we can do:
			// dp[w] = max profit with w items
			// Initialize dp with -infinity except dp[0] = 0
			// For each item type j with profit p = profitPerUnit[j]:
			//   if p <= 0, skip
			//   for w from k down to 0:
			//     for count from 1 to min(c[j], k-w):
			//       if dp[w] != -inf:
			//         dp[w+count] = max(dp[w+count], dp[w] + count * p)

			// But this is O(m * k * k) which is 100 * 100 * 100 = 1e6 per pair, and 10*9=90 pairs, so 9e7 which might be too slow.

			// Better approach: since each item has weight 1, we can think of it as:
			// We have m types of items, each with a profit per unit p_j and max count c_j.
			// We want to choose quantities q_j such that sum(q_j) <= k and maximize sum(q_j * p_j).
			// This is equivalent to: we have a multiset of items where item type j appears c_j times, each with value p_j.
			// We want to pick at most k items with maximum total value.
			// So we can just collect all items (with their profits), sort by profit descending, and take the top k.

			// Let's do that:
			type Item struct {
				profit int
			}
			items := make([]Item, 0)
			for j := 0; j < m; j++ {
				p := planets[sellPlanet].b[j] - planets[buyPlanet].a[j]
				if p > 0 {
					for count := 0; count < planets[buyPlanet].c[j]; count++ {
						items = append(items, Item{profit: p})
					}
				}
			}

			// Sort items by profit descending
			// We can use a simple sort
			for i := 0; i < len(items); i++ {
				for j := i + 1; j < len(items); j++ {
					if items[j].profit > items[i].profit {
						items[i], items[j] = items[j], items[i]
					}
				}
			}

			// Take top min(k, len(items)) items
			takeCount := k
			if takeCount > len(items) {
				takeCount = len(items)
			}

			profit := 0
			for i := 0; i < takeCount; i++ {
				profit += items[i].profit
			}

			if profit > maxProfit {
				maxProfit = profit
			}
		}
	}

	fmt.Println(maxProfit)
}
