package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strings"
)

type item struct {
	profit int
	count  int
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m, k int
	fmt.Fscan(reader, &n, &m, &k)

	// planets[i][j] = {buyPrice, sellPrice, count}
	planets := make([][3][]int, n)
	for i := 0; i < n; i++ {
		// Read planet name
		line, _ := reader.ReadString('\n')
		_ = line // planet name, not needed

		planets[i] = make([][3]int, m)
		for j := 0; j < m; j++ {
			var a, b, c int
			fmt.Fscan(reader, &a, &b, &c)
			planets[i][j] = [3]int{a, b, c}
		}
	}

	maxProfit := 0

	// Try all pairs of buy planet and sell planet
	for buyPlanet := 0; buyPlanet < n; buyPlanet++ {
		for sellPlanet := 0; sellPlanet < n; sellPlanet++ {
			if buyPlanet == sellPlanet {
				continue
			}

			// For each item type, calculate profit per item and available count
			items := make([]item, 0, m)
			for j := 0; j < m; j++ {
				buyPrice := planets[buyPlanet][j][0]
				sellPrice := planets[sellPlanet][j][1]
				count := planets[buyPlanet][j][2]

				profit := sellPrice - buyPrice
				if profit > 0 && count > 0 {
					items = append(items, item{profit: profit, count: count})
				}
			}

			// Sort by profit descending
			sort.Slice(items, func(i, j int) bool {
				return items[i].profit > items[j].profit
			})

			// Greedily take items with highest profit first
			remaining := k
			profit := 0
			for _, it := range items {
				if remaining <= 0 {
					break
				}
				take := it.count
				if take > remaining {
					take = remaining
				}
				profit += take * it.profit
				remaining -= take
			}

			if profit > maxProfit {
				maxProfit = profit
			}
		}
	}

	fmt.Fprintln(writer, maxProfit)
}
