			cij, _ := fmt.Sscanf(parts[2], "%d")
			a[i][j] = aij
			b[i][j] = bij
			c[i][j] = cij
		}
	}

	// For each pair of planets (buy from buyPlanet, sell to sellPlanet)
	// We want to maximize profit = sum over items of (sellPrice - buyPrice) * quantity
	// subject to:
	//   quantity_j <= c[buyPlanet][j]
	//   sum of quantity_j <= k
	//   quantity_j >= 0
	//
	// This is a bounded knapsack problem where:
	//   weight of item j = 1
	//   value of item j = b[sellPlanet][j] - a[buyPlanet][j]
	//   max quantity of item j = c[buyPlanet][j]
	//   capacity = k
	//
	// We only care about items where value > 0.

	maxProfit := 0

	for buyPlanet := 0; buyPlanet < n; buyPlanet++ {
		for sellPlanet := 0; sellPlanet < n; sellPlanet++ {
			if buyPlanet == sellPlanet {
				continue
			}
			// dp[t] = max profit using t items
			dp := make([]int, k+1)
			// initialize with 0 (no items)
			for t := 0; t <= k; t++ {
				dp[t] = 0
			}

			// For each item type
			for j := 0; j < m; j++ {
				profitPerItem := b[sellPlanet][j] - a[buyPlanet][j]
				if profitPerItem <= 0 {
					continue
				}
				maxQty := c[buyPlanet][j]
				if maxQty > k {
					maxQty = k
				}
				// Bounded knapsack: we can take 0 to maxQty of this item
				// Use a copy of dp to avoid using the same item multiple times in one iteration
				newDp := make([]int, k+1)
				for t := 0; t <= k; t++ {
					newDp[t] = dp[t]
				}
				for t := 0; t <= k; t++ {
					// Try taking q items of type j, where q goes from 1 to min(maxQty, k-t)
					maxQ := maxQty
					if k-t < maxQ {
						maxQ = k - t
					}
					for q := 1; q <= maxQ; q++ {
						candidate := dp[t] + q*profitPerItem
						if candidate > newDp[t+q] {
							newDp[t+q] = candidate
						}
					}
				}
				// Update dp
				for t := 0; t <= k; t++ {
					dp[t] = newDp[t]
				}
			}

			// Find max profit for this pair
			for t := 0; t <= k; t++ {
				if dp[t] > maxProfit {
					maxProfit = dp[t]
				}
			}
		}
	}

	fmt.Println(maxProfit)
}
