func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	var n, m, k int
	fmt.Fscan(reader, &n, &m, &k)

	// planets[i][j] = {a, b, c}
	planets := make([][3][]int, n)
	for i := 0; i < n; i++ {
		// read planet name
		line, _ := reader.ReadString('\n')
		_ = line // we don't need the name
		planets[i] = make([][3]int, m)
		for j := 0; j < m; j++ {
			var a, b, c int
			fmt.Fscan(reader, &a, &b, &c)
			planets[i][j] = [3]int{a, b, c}
		}
	}

	// For each pair of planets (buy on i, sell on j), i != j
	// We want to maximize profit with at most k items total.
	// For each item type t, if we buy on planet i and sell on planet j:
	//   profit per item = b[j][t] - a[i][t]
	//   max we can buy of type t = c[i][t]
	// We can choose how many of each type to buy, total <= k.
	// This is a bounded knapsack / multiple choice knapsack.

	maxProfit := 0

	for buyPlanet := 0; buyPlanet < n; buyPlanet++ {
		for sellPlanet := 0; sellPlanet < n; sellPlanet++ {
			if buyPlanet == sellPlanet {
				continue
			}

			// For each item type, compute profit per item and max quantity
			// We'll use a DP: dp[x] = max profit using exactly x items (or at most x)
			// Actually, let's do dp[x] = max profit with x items total.
			// We process each item type one by one.

			dp := make([]int, k+1)
			// initialize with 0 (no items, no profit)
			// But we need to handle the case where we can't buy some items.
			// Let's use -infinity for unreachable states.
			const negInf = -1 << 30
			for x := 1; x <= k; x++ {
				dp[x] = negInf
			}
			dp[0] = 0

			for t := 0; t < m; t++ {
				profitPerItem := planets[sellPlanet][t][1] - planets[buyPlanet][t][0]
				maxQty := planets[buyPlanet][t][2]

				if profitPerItem <= 0 || maxQty == 0 {
					continue
				}

				// newDp: after considering item type t
				newDp := make([]int, k+1)
				for x := 0; x <= k; x++ {
					newDp[x] = dp[x]
				}

				// For each possible number of items of type t we buy (0 to maxQty, but also limited by remaining capacity)
				for x := 0; x <= k; x++ {
					if dp[x] == negInf {
						continue
					}
					// buy q items of type t, q from 1 to min(maxQty, k-x)
					maxQ := maxQty
					if k-x < maxQ {
						maxQ = k - x
					}
					for q := 1; q <= maxQ; q++ {
						newProfit := dp[x] + q*profitPerItem
						if newProfit > newDp[x+q] {
							newDp[x+q] = newProfit
						}
					}
				}

				dp = newDp
			}

			// The answer for this pair is the max over all x from 0 to k of dp[x]
			for x := 0; x <= k; x++ {
				if dp[x] > maxProfit {
					maxProfit = dp[x]
				}
			}
		}
	}

	fmt.Fprintln(writer, maxProfit)
}
