	fmt.Fscan(reader, &n, &m, &k)

	// a[i][j] = buy price on planet i for item j
	// b[i][j] = sell price on planet i for item j
	// c[i][j] = available items on planet i for item j
	a := make([][]int, n)
	b := make([][]int, n)
	c := make([][]int, n)

	for i := 0; i < n; i++ {
		// Read planet name
		line, _ := reader.ReadString('\n')
		_ = line // planet name, we don't need it

		a[i] = make([]int, m)
		b[i] = make([]int, m)
		c[i] = make([]int, m)

		for j := 0; j < m; j++ {
			fmt.Fscan(reader, &a[i][j], &b[i][j], &c[i][j])
		}
	}

	// For each pair of planets (buy planet i, sell planet j), i != j
	// We want to maximize profit = sum over items of (sell_price - buy_price) * quantity
	// subject to:
	//   total quantity <= k
	//   quantity of item t on planet i <= c[i][t]
	//   quantity >= 0
	//   We only buy items where sell_price > buy_price (otherwise no profit)

	maxProfit := 0

	for buyPlanet := 0; buyPlanet < n; buyPlanet++ {
		for sellPlanet := 0; sellPlanet < n; sellPlanet++ {
			if buyPlanet == sellPlanet {
				continue
			}

			// For each item type, compute the profit per item if we buy on buyPlanet and sell on sellPlanet
			// profit[j] = b[sellPlanet][j] - a[buyPlanet][j]
			// We can buy up to c[buyPlanet][j] items of type j
			// We want to pick quantities q[j] such that sum q[j] <= k, 0 <= q[j] <= c[buyPlanet][j]
			// to maximize sum q[j] * profit[j]

			// This is a bounded knapsack problem where each item type has a "value" of profit[j] per unit
			// and we can take up to c[buyPlanet][j] units, with total capacity k.

			// Since m and k are up to 100, we can do DP.
			// dp[x] = max profit using x items total
			// For each item type j, we can take 0 to min(c[buyPlanet][j], k) units.

			dp := make([]int, k+1)
			// Initialize dp with 0 (we can always choose 0 items)

			for j := 0; j < m; j++ {
				profitPerItem := b[sellPlanet][j] - a[buyPlanet][j]
				if profitPerItem <= 0 {
					continue // no profit, skip
				}
				maxQty := c[buyPlanet][j]
				if maxQty > k {
					maxQty = k
				}

				// Bounded knapsack: for each capacity from k down to 0, try adding 1 to maxQty items of type j
				// To optimize, we can use the standard technique for bounded knapsack.
				// But since k and maxQty are small (<=100), we can do a simple loop.

				// New dp array
				newDp := make([]int, k+1)
				for x := 0; x <= k; x++ {
					newDp[x] = dp[x]
				}

				// For each current capacity x, try adding t items of type j (t from 1 to maxQty)
				// such that x + t <= k
				for x := 0; x <= k; x++ {
					for t := 1; t <= maxQty && x+t <= k; t++ {
						val := dp[x] + t*profitPerItem
						if val > newDp[x+t] {
							newDp[x+t] = val
						}
					}
				}
				dp = newDp
			}

			// The max profit for this pair is max over dp[x] for x from 0 to k
			for x := 0; x <= k; x++ {
				if dp[x] > maxProfit {
					maxProfit = dp[x]
				}
			}
		}
	}

	fmt.Println(maxProfit)
}
