	// This is a bounded knapsack problem where:
	//   weight of item j = 1
	//   value of item j = b[j][item] - a[i][item] (only if positive)
	//   max count of item j = c[i][item]
	//   capacity = k
	//
	// We can use DP: dp[x] = max profit using x items
	// But since each item type has a limited count and value, we can use a standard bounded knapsack.

	maxProfit := 0

	for buyPlanet := 0; buyPlanet < n; buyPlanet++ {
		for sellPlanet := 0; sellPlanet < n; sellPlanet++ {
			if buyPlanet == sellPlanet {
				continue
			}

			// dp[x] = max profit with x items
			dp := make([]int, k+1)
			// Initialize to 0 (we can always choose 0 items)

			// For each item type
			for item := 0; item < m; item++ {
				profitPerItem := b[sellPlanet][item] - a[buyPlanet][item]
				if profitPerItem <= 0 {
					continue
				}
				maxCount := c[buyPlanet][item]
				if maxCount > k {
					maxCount = k
				}

				// Bounded knapsack: we can take up to maxCount items of this type
				// Each item has weight 1 and value profitPerItem
				// We update dp in reverse order to avoid using the same item multiple times in one iteration
				// Actually for bounded knapsack with weight 1, we can do:
				// for x from k down to 1:
				//   dp[x] = max(dp[x], dp[x-1] + profitPerItem) but limited by how many we've taken
				// Better approach: use a separate array or use the standard technique.

				// Since weight is 1, we can think of it as: we can add up to maxCount items each giving profitPerItem.
				// We can do:
				// new_dp = dp (copy)
				// for x from 1 to k:
				//   for t from 1 to min(maxCount, x):
				//     new_dp[x] = max(new_dp[x], dp[x-t] + t*profitPerItem)
				// But this is O(k * maxCount * m) which might be too slow.

				// Alternative: since weight is 1, we can use a simpler approach.
				// We can use a 2D DP or just iterate.
				// Actually, let's use the standard bounded knapsack with binary decomposition or just a simple loop.

				// Simple approach: for each possible number of items taken (1 to maxCount), update dp
				// But we need to be careful not to use the same "batch" multiple times.

				// Let's use a temporary array
				newDp := make([]int, k+1)
				copy(newDp, dp)

				for x := 1; x <= k; x++ {
					// We can take t items of this type, where t is from 1 to min(maxCount, x)
					// newDp[x] = max over t of (dp[x-t] + t*profitPerItem)
					// But we also keep newDp[x] which is dp[x] (taking 0 of this type)
					best := newDp[x]
					maxT := maxCount
					if maxT > x {
						maxT = x
					}
					for t := 1; t <= maxT; t++ {
						val := dp[x-t] + t*profitPerItem
						if val > best {
							best = val
						}
					}
					newDp[x] = best
				}
				copy(dp, newDp)
			}

			// After processing all items, dp[x] is the max profit using exactly x items
			// We want the max over all x from 0 to k
			for x := 0; x <= k; x++ {
				if dp[x] > maxProfit {
					maxProfit = dp[x]
				}
			}
		}
	}

	fmt.Println(maxProfit)
}
